model Doc {
  slug    String @id
  body    String /// @encrypted
}

model Row {
  id    Int    @id @default(autoincrement())
  ref   String @unique /// @encryption:cursor
  data  String /// @encrypted
}

model Person {
  id       Int     @id @default(autoincrement())
  email    String  /// @encrypted
  emailHash String? /// @encryption:hash(email)?normalize=lowercase&normalize=trim&algorithm=sha512
}

